58	  std::complex<double> Fvf_wrapper(int st, int j1, int j2, int j3, int j4, int j5, int j6,
59	                                    std::complex<double>* fza, std::complex<double>* fzb) {
60	    using namespace mxpart_mod;
61	    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
62	    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);
63	    return Fvf(st, j1, j2, j3, j4, j5, j6, za, zb);
64	  }
65	}
